#ifndef _VALOR_EXPT_VERSION_H_ 
#define _VALOR_EXPT_VERSION_H_ 
/* 
 * Version information automatically generated by the VALOR/EXPT installer 
 * 
 * These macros can be used in the following way (as the ones at ROOT's RVersion.h): 
 * #if __VALOR_EXPT_RELEASE_CODE__ >= GRELCODE(2,4,11) 
 * #include <newheader.h>
 * #else
 * #include <oldheader.h>
 * #endif
*/ 

#define VALOR_EXPT_RELEASE_CODE_BUILDER(a,b,c) (((a) << 16) + ((b) << 8) + (c)) 

#define __VALOR_EXPT_RELEASE__      "1.1.0"
#define __VALOR_EXPT_RELEASE_CODE__ VALOR_EXPT_RELEASE_CODE_BUILDER(1,1,0) 

#endif

